/* =====================================================================
   WINKYMON — Winky Community game plugin  (SINGLE FILE)
   Drop this ONE file at:  plugins/winkymon.js
   Nothing else to upload. The whole game is embedded below (base64) and
   runs isolated in a blob-iframe, so it can't clash with the app's CSS/JS.
   Bridges net/storage/contacts to Supabase using the app's rest()/insert().
   Requires winkymon_supabase.sql (avatars, records, events) run once.
   The challenge/accept handshake reuses your existing game_challenges
   table with from_char = 'wm'.
   ===================================================================== */
(function(){
  'use strict';

  /* ---- helpers to build the game document from the embedded base64 ---- */
  function gameBlobURL(){
    var bin = atob(WINKYMON_GAME_B64);
    var len = bin.length, bytes = new Uint8Array(len);
    for(var i=0;i<len;i++) bytes[i]=bin.charCodeAt(i);
    var blob = new Blob([bytes], {type:'text/html'});
    return URL.createObjectURL(blob);
  }

  function register(){
    if(!window.WinkyGames){ setTimeout(register, 200); return; }
    WinkyGames.register({
      id:'winkymon',
      challengeIcon:function(){ var d=el('div',null,'\u2726'); d.style.fontSize='40px'; d.style.textAlign='center'; d.style.width='46px'; return d; },
      openChallenge: async function(threadId, otherId, otherNick){
        var chId=null;
        try{
          var rows=await insert('/game_challenges',{ from_id:App.me.id, from_nick:App.me.nickname, to_id:otherId, from_char:'wm', status:'pending', updated_at:new Date().toISOString() });
          chId=rows&&rows.length?rows[0].id:null;
        }catch(e){ toast('Error'); return; }
        toast(T('challengeSent'));
        var ov=showWaiting(T('waitAccept')); var tries=0;
        var poll=setInterval(async function(){ tries++;
          try{
            var r=await rest('/game_challenges?id=eq.'+chId+'&select=status');
            var st=(r&&r.length)?r[0].status:null;
            if(st==='accepted'){ clearInterval(poll); ov.remove(); openArena(otherId, otherNick, true, chId); }
            else if(st==='declined'){ clearInterval(poll); ov.remove(); toast(T('declinedGame')); }
            else if(tries>80){ clearInterval(poll); ov.remove(); }
          }catch(e){}
        },1500);
        ov._cancel=function(){ clearInterval(poll); try{ rest('/game_challenges?id=eq.'+chId,{method:'PATCH',body:{status:'declined',updated_at:new Date().toISOString()}}); }catch(e){} };
      },
      acceptChallenge: async function(ch){
        try{ await rest('/game_challenges?id=eq.'+ch.id,{method:'PATCH',body:{status:'accepted',updated_at:new Date().toISOString()}}); }catch(e){}
        openArena(ch.from_id, ch.from_nick, false, ch.id);
      }
    });
  }

  function showWaiting(text){
    var ov=document.createElement('div');
    ov.style.cssText='position:fixed;inset:0;z-index:64;display:grid;place-items:center;background:rgba(6,10,22,.8)';
    var card=document.createElement('div');
    card.style.cssText='background:#161b22;border:1px solid #2a3a44;border-radius:14px;padding:22px;color:#e6edf3;text-align:center;min-width:240px';
    card.innerHTML='<div style="font-size:34px;margin-bottom:8px">\u2726</div><div style="margin-bottom:14px">'+text+'</div>';
    var x=document.createElement('button'); x.className='btn dark'; x.textContent=T('cancel');
    x.onclick=function(){ if(ov._cancel)ov._cancel(); ov.remove(); };
    card.appendChild(x); ov.appendChild(card); document.body.appendChild(ov);
    return ov;
  }

  async function getRecord(aId,bId){
    var a=[String(aId),String(bId)].sort(), lo=a[0], hi=a[1];
    try{
      var r=await rest('/winkymon_records?a=eq.'+encodeURIComponent(lo)+'&b=eq.'+encodeURIComponent(hi)+'&select=*');
      if(!r||!r.length) return {mine:0,theirs:0};
      var mineIsLo=(String(aId)===lo);
      return { mine: mineIsLo?r[0].a_wins:r[0].b_wins, theirs: mineIsLo?r[0].b_wins:r[0].a_wins };
    }catch(e){ return {mine:0,theirs:0}; }
  }
  async function addWin(winId,loseId){
    var a=[String(winId),String(loseId)].sort(), lo=a[0], hi=a[1];
    var winnerIsLo=(String(winId)===lo);
    try{
      var r=await rest('/winkymon_records?a=eq.'+encodeURIComponent(lo)+'&b=eq.'+encodeURIComponent(hi)+'&select=*');
      var row=(r&&r.length)?r[0]:{a:lo,b:hi,a_wins:0,b_wins:0};
      if(winnerIsLo) row.a_wins=(row.a_wins||0)+1; else row.b_wins=(row.b_wins||0)+1;
      row.updated_at=new Date().toISOString();
      await rest('/winkymon_records',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:row});
    }catch(e){}
  }

  function openArena(peerId, peerName, isHost, matchId){
    matchId=String(matchId);
    var me=App.me.id, myName=App.me.nickname;
    var url=gameBlobURL();

    var ov=document.createElement('div');
    ov.style.cssText='position:fixed;inset:0;z-index:65;background:#000';
    var frame=document.createElement('iframe');
    frame.src=url; frame.allow='autoplay';
    frame.style.cssText='width:100%;height:100%;border:0;display:block';
    ov.appendChild(frame);
    var x=document.createElement('button'); x.textContent='\u2715';
    x.style.cssText='position:absolute;top:calc(env(safe-area-inset-top,0px) + 8px);right:10px;z-index:9;width:38px;height:38px;border:2px solid #000;background:rgba(0,0,0,.5);color:#fff;font-size:16px;cursor:pointer';
    x.onclick=function(){ cleanup(); };
    ov.appendChild(x);
    document.body.appendChild(ov);

    var lastEventId=0, netPoll=null;
    async function pollEvents(){
      try{
        var rows=await rest('/winkymon_events?match_id=eq.'+encodeURIComponent(matchId)+'&sender_id=neq.'+me+'&id=gt.'+lastEventId+'&order=id.asc&limit=200');
        (rows||[]).forEach(function(r){ if(r.id>lastEventId)lastEventId=r.id; frame.contentWindow.postMessage({wm:1,kind:'net',msg:r.payload},'*'); });
      }catch(e){}
    }
    async function onMsg(e){
      if(e.source!==frame.contentWindow) return;
      var d=e.data; if(!d||!d.wm) return;
      if(d.kind==='ready'){
        /* Winky Community profile avatars: mine from App.me, opponent via REST.
           avatar_url = uploaded image; else avatar_id -> colored letter fallback. */
        var myAvatarUrl = (App.me&&App.me.avatar_url)||null;
        var myAvatarId  = (App.me&&App.me.avatar_id!=null)?App.me.avatar_id:0;
        var peerAvatarUrl=null, peerAvatarId=0;
        try{
          var pu=await rest('/users?id=eq.'+encodeURIComponent(peerId)+'&select=avatar_id,avatar_url');
          if(pu&&pu.length){ peerAvatarUrl=pu[0].avatar_url||null; peerAvatarId=(pu[0].avatar_id!=null)?pu[0].avatar_id:0; }
        }catch(_e){}
        frame.contentWindow.postMessage({wm:1,kind:'start',me:me,peer:peerId,isHost:isHost,
          myName:myName,peerName:peerName,
          myAvatarUrl:myAvatarUrl,myAvatarId:myAvatarId,
          peerAvatarUrl:peerAvatarUrl,peerAvatarId:peerAvatarId},'*');
        /* baseline = 0: match_id (challenge id) is unique per match, and we
           filter sender_id != me, so deliver ALL peer events from the start.
           This avoids skipping the opponent's first ready/team messages. */
        lastEventId=0;
        if(netPoll) clearInterval(netPoll); netPoll=setInterval(pollEvents, 700);
        pollEvents();
      } else if(d.kind==='net'){
        try{ await insert('/winkymon_events',{match_id:matchId,sender_id:me,payload:d.msg,created_at:new Date().toISOString()}); }catch(_e){}
      } else if(d.kind==='req'){
        var p=d.payload||{}, res=null;
        try{
          if(d.type==='loadAvatar'){ var a=await rest('/winkymon_avatars?user_id=eq.'+encodeURIComponent(p.uid)+'&select=avatar'); res=(a&&a.length)?a[0].avatar:null; }
          else if(d.type==='saveAvatar'){ await rest('/winkymon_avatars',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:{user_id:p.uid,avatar:p.av,updated_at:new Date().toISOString()}}); res=true; }
          else if(d.type==='getRecord'){ res=await getRecord(p.a,p.b); }
          else if(d.type==='addWin'){ await addWin(p.w,p.l); res=true; }
        }catch(_e){}
        frame.contentWindow.postMessage({wm:1,kind:'res',id:d.id,payload:res},'*');
      } else if(d.kind==='exit'){ cleanup(); }
    }
    window.addEventListener('message', onMsg);
    function cleanup(){
      window.removeEventListener('message', onMsg);
      if(netPoll) clearInterval(netPoll);
      try{ URL.revokeObjectURL(url); }catch(_e){}
      try{ ov.remove(); }catch(_e){}
      try{ rest('/winkymon_events?match_id=eq.'+encodeURIComponent(matchId)+'&sender_id=eq.'+me,{method:'DELETE'}); }catch(_e){}
    }
  }

  /* ---- embedded game (base64 of the full standalone HTML) ---- */
  var WINKYMON_GAME_B64 =
  "";

  register();
})();
